<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();$aid=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT a.*,s.name subject FROM assignments a JOIN subjects s ON s.id=a.subject_id WHERE a.id=? AND a.status=\'published\' AND a.deleted_at IS NULL');$q->execute([$aid]);$a=$q->fetch();if(!$a)exit('Assignment not found');$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){if(strtotime($a['deadline'])<time()){$err='Submission deadline has passed.';}else{try{$path=null;if(!empty($_FILES['file']['name'])){$x=FileService::save($_FILES['file'],'assignment-submissions',['pdf'=>['application/pdf'],'doc'=>['application/msword'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],'zip'=>['application/zip'],'txt'=>['text/plain']]);$path=$x['path'];}$q2=db()->prepare('INSERT INTO assignment_submissions(assignment_id,student_id,file_path,answer_text,status) VALUES(?,?,?,?,\'submitted\') ON DUPLICATE KEY UPDATE file_path=VALUES(file_path),answer_text=VALUES(answer_text),submitted_at=NOW(),status=\'submitted\'');$q2->execute([$aid,$sid,$path,$_POST['answer_text']??'']);$_SESSION['flash']=['success','Assignment submitted'];redirect('assignments.php');}catch(Throwable $e){$err=$e->getMessage();}}}page_top('Submit Assignment');flash();if(!empty($err))echo '<div class="alert alert-danger">'.e($err).'</div>';?><div class='card p-4'><h4><?=e($a['title'])?></h4><p><?=e($a['description'])?></p><p class='text-muted'><?=e($a['subject'])?> · Deadline <?=e($a['deadline'])?> · Max <?=e($a['max_marks'])?></p><form method='post' enctype='multipart/form-data'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='id' value='<?=e($aid)?>'><textarea name='answer_text' class='form-control mb-3' placeholder='Answer / notes'></textarea><input type='file' name='file' class='form-control mb-3'><button class='btn btn-primary'>Submit Assignment</button></form></div><?php page_bottom();
